css:
/* ===== 黑曜蓝图 · Hyperstudio：obsidian 底 + 发丝线网格 + 图纸标注 ===== */

/* 点阵纹理画布，关掉极光 */
.aurora { display: none; }
body {
  background-color: #101010;
  background-image: radial-gradient(circle, rgba(243,243,243,.05) 1px, transparent 1.2px);
  background-size: 26px 26px;
  font-size: 16px; line-height: 1.55;
}
::selection { background: #f3f3f3; color: #101010; }
html, body { overflow-x: hidden; }

/* ===== 顶栏：透明 + 永久发丝底线，链接全大写、细线下划线指示 ===== */
header { background: transparent; backdrop-filter: none; -webkit-backdrop-filter: none; border-bottom: 1px solid #212121; padding: 20px 40px; }
header.scrolled { border-bottom-color: #212121; background: #101010; }
.brand h1 { font-weight: 400; font-size: 18px; letter-spacing: -.01em; }
.brand h1 em { color: #6f6759; }
.brand .sub { font-family: var(--font-num); font-size: 10px; letter-spacing: .34em; text-transform: uppercase; }
nav { background: transparent; border: 0; border-radius: 0; padding: 0; gap: 26px; backdrop-filter: none; }
nav button { border-radius: 0; padding: 6px 0; font: 400 12px/1 var(--font-body); letter-spacing: .18em; text-transform: uppercase; color: #9c9c9c; border-bottom: 1px solid transparent; transition: color .2s, border-color .2s; }
nav button:hover { color: #f3f3f3; }
nav button.active { background: transparent; color: #f3f3f3; border-bottom-color: #f3f3f3; }
#theme-switch { border-radius: 0; background: transparent; border-color: #212121; font: 400 11px/1 var(--font-num); letter-spacing: .08em; color: #9c9c9c; }
#theme-switch:hover { border-color: #f3f3f3; color: #f3f3f3; }
main { max-width: 1200px; }

/* ===== 按钮：主按钮=唯一白色胶囊，其余=描边直角 ===== */
.btn { border-radius: 0; border: 1px solid #f3f3f3; background: transparent; color: #f3f3f3; font: 400 13px/1 var(--font-body); letter-spacing: .16em; text-transform: uppercase; padding: 14px 26px; backdrop-filter: none; }
.btn:hover { border-color: #ffffff; background: rgba(255,255,255,.05); transform: none; }
.btn.primary { background: #ffffff; border-color: #ffffff; color: #101010; border-radius: 9999px; font-weight: 400; }
.btn.primary:hover { filter: none; box-shadow: none; background: #f3f3f3; }
.btn.ghost { background: transparent; }

/* ===== 落地页 ===== */
#landing { max-width: 680px; margin-top: 15vh; gap: 24px; }
#landing .mark { border-radius: 0; background: transparent; border-color: #212121; box-shadow: none; animation: none; font-weight: 400; font-size: 38px; color: #f3f3f3; }
#landing h2 { font-weight: 400; font-size: 34px; letter-spacing: -.02em; line-height: 1.2; }
#landing p { font-size: 15px; color: #9c9c9c; }
.hint { font-family: var(--font-num); font-size: 11px; letter-spacing: .06em; }

/* ===== Hero：Headline Display Block —— 63px weight 400 负字距，下方白色胶囊 CTA ===== */
.hero { padding: 100px 0 0; min-height: 0; align-items: start; border-bottom: 1px solid #212121; }
.hello { font-family: var(--font-num); font-size: 11px; letter-spacing: .34em; color: #9c9c9c; margin-bottom: 28px; }
.hello::before { width: 44px; background: #6f6759; }
.hero-title { font-weight: 400; font-size: clamp(44px, 5.4vw, 63px); line-height: 1.05; letter-spacing: -.011em; margin-bottom: 26px; }
.hero-title .hl { background: none; -webkit-background-clip: initial; background-clip: initial; color: #f3f3f3; }
.hero-title.long { font-weight: 400; font-size: clamp(26px, 3vw, 38px); line-height: 1.3; letter-spacing: -.01em; }
.hero-essence { font-size: 16px; color: #9c9c9c; max-width: 56ch; margin-bottom: 22px; }
.hero-essence strong { color: #f3f3f3; font-weight: 400; }

/* 趋势条 → Status Badge 体系：#1a1a1a 底 + Graphite 描边 + 等宽大写 */
.trend-row { gap: 8px; margin: 0 0 26px; }
.trend { border-radius: 0; background: #1a1a1a; border-color: #212121; backdrop-filter: none; font-family: var(--font-num); font-size: 10px; letter-spacing: .12em; text-transform: uppercase; color: #9c9c9c; padding: 7px 13px; }
.trend b { color: #f3f3f3; font-weight: 400; }

/* 星云标签：直角描边 + 等宽字体，像图纸上的标注气泡 */
.neb-tag { border-radius: 0; background: transparent; border-color: #212121; backdrop-filter: none; box-shadow: none; font-family: var(--font-num); font-size: 11px; letter-spacing: .06em; color: #9c9c9c; padding: 7px 14px; }
.neb-tag:hover { border-color: #f3f3f3; color: #f3f3f3; }
.neb-tag b { font-weight: 400; color: #f3f3f3; }

/* ===== 统计区 → Service Card 2×2 Grid Cell：整块发丝线框架 + 单元格编号 ===== */
.stat-row { gap: 0; border: 1px solid #212121; margin: 72px 0 0; perspective: none; counter-reset: statcell; }
.stat { background: transparent; border: 0; border-left: 1px solid #212121; border-radius: 0; padding: 36px 30px 32px; box-shadow: none; backdrop-filter: none; transform: none !important; counter-increment: statcell; }
.stat:first-child { border-left: 0; }
.stat::after { content: "0" counter(statcell); position: absolute; top: 18px; right: 22px; font-family: var(--font-num); font-size: 10px; letter-spacing: .18em; color: #474747; }
.stat:hover { border-color: #212121; background: rgba(255,255,255,.02); }
.stat .num { font-weight: 400; font-size: 44px; letter-spacing: -.02em; color: #f3f3f3; transform: none; }
.stat .label { font-family: var(--font-num); font-size: 10px; letter-spacing: .22em; text-transform: uppercase; color: #9c9c9c; margin-top: 14px; transform: none; }
.stat .spark { display: none; }

/* ===== 面板区：Section Divider 节奏 —— 区块间 72px 留白 + 各自发丝线框架 ===== */
.dash-grid { gap: 0; border: 1px solid #212121; margin-top: 72px; }
.panel { background: transparent; border: 0; border-radius: 0; padding: 40px; box-shadow: none; backdrop-filter: none; }
.panel:hover { border-color: #212121; }
.dash-grid > .panel { border-left: 0; }
.rail { gap: 0; border-left: 1px solid #212121; }
.rail .panel { border: 0; border-top: 1px solid #212121; }
.rail .panel:first-child { border-top: 0; }
.panel h3 { font-family: var(--font-num); font-weight: 400; font-size: 11px; letter-spacing: .3em; text-transform: uppercase; color: #9c9c9c; margin-bottom: 26px; }
.panel h3::after { background: #212121; }
.persona-md h1, .persona-md h2 { font-weight: 400; color: #f3f3f3; font-size: 21px; letter-spacing: -.01em; }
.persona-md strong { color: #f3f3f3; font-weight: 400; }
.persona-md blockquote { border-left-color: #6f6759; }
.tag-bar .track { background: #1a1a1a; border-radius: 0; height: 3px; }
.tag-bar .fill { background: #f3f3f3; border-radius: 0; }
.tag-bar .count { font-family: var(--font-num); }
.material-item { border-bottom-color: #212121; }
.material-item .dot { background: #6f6759; opacity: 1; }
.mini-plan { border-bottom-color: #212121; }
.mini-plan .mp-t { font-weight: 400; }
.mini-plan:hover .mp-t { color: #f3f3f3; }
.mini-plan .mp-bar { background: #1a1a1a; border-radius: 0; height: 3px; }
.mini-plan .mp-fill { background: #f3f3f3; border-radius: 0; }

/* ===== 卡片页 → Portfolio Card：发丝线网格单元格 + 大字索引编号 ===== */
.toolbar { margin: 40px 0 30px; }
.chip { border-radius: 0; background: transparent; border-color: #212121; backdrop-filter: none; font: 400 11px/1 var(--font-num); letter-spacing: .1em; text-transform: uppercase; padding: 9px 14px; }
.chip:hover { transform: none; border-color: #f3f3f3; color: #f3f3f3; }
.chip.active { background: #f3f3f3; border-color: #f3f3f3; color: #101010; }
.search-box { border-radius: 0; background: transparent; border-color: #212121; backdrop-filter: none; font: 400 12px/1 var(--font-num); letter-spacing: .04em; }
.search-box:focus { border-color: #f3f3f3; }
#cards-grid { gap: 0 !important; perspective: none !important; border: 1px solid #212121; border-width: 1px 0 0 1px; counter-reset: kcard; }
.card-grid { gap: 0; border: 1px solid #212121; border-width: 1px 0 0 1px; perspective: none; counter-reset: kcard; }
.kcard { background: transparent; border: 1px solid #212121; border-width: 0 1px 1px 0; border-radius: 0; padding: 36px 30px 32px; box-shadow: none; backdrop-filter: none; gap: 15px; transform: none !important; position: relative; counter-increment: kcard; }
.kcard::before { content: counter(kcard, decimal-leading-zero); position: absolute; top: 16px; right: 20px; font-family: var(--font-num); font-size: 11px; letter-spacing: .16em; color: #474747; }
.kcard:hover { border-color: #212121; background: rgba(255,255,255,.02); }
.kcard .ctitle { font-weight: 400; font-size: 18px; letter-spacing: -.01em; line-height: 1.5; color: #f3f3f3; transform: none; padding-right: 34px; }
.kcard .cmeta { font-family: var(--font-num); font-size: 11px; letter-spacing: .06em; text-transform: uppercase; transform: none; }
.kcard .cmeta span + span::before { content: "/ "; color: #474747; }
.kcard .csummary { font-size: 14px; color: #9c9c9c; transform: none; }
.kcard .ctags { transform: none; }
.mini-tag { background: transparent; border: 1px solid #212121; border-radius: 0; color: #9c9c9c; font-family: var(--font-num); font-size: 10px; letter-spacing: .08em; padding: 4px 10px; }

/* ===== 洞察页：编号 + 发丝线框架 ===== */
.insight-grid { gap: 0; border: 1px solid #212121; margin-top: 40px; counter-reset: ipanel; }
.insight-grid .panel { border: 0; border-top: 1px solid #212121; position: relative; counter-increment: ipanel; }
.insight-grid .panel:first-child { border-top: 0; }
.insight-grid .panel:not(.wide):nth-child(even) { border-left: 1px solid #212121; }
.insight-grid .panel::before { content: "0" counter(ipanel); position: absolute; top: 20px; right: 24px; font-family: var(--font-num); font-size: 10px; letter-spacing: .18em; color: #474747; }
.insight-grid .panel h3 { padding-right: 48px; }

/* 判断框架墙：发丝线网格单元格 + 等宽编号 */
.fw-wall { gap: 0; border: 1px solid #212121; border-width: 1px 0 0 1px; counter-reset: fw; }
.fw-card { background: transparent; border: 1px solid #212121; border-width: 0 1px 1px 0; border-radius: 0; padding: 30px 26px 28px; box-shadow: none; backdrop-filter: none; position: relative; counter-increment: fw; transition: background .2s; }
.fw-card::before { content: counter(fw, decimal-leading-zero); position: absolute; top: 14px; right: 18px; font-family: var(--font-num); font-size: 10px; letter-spacing: .16em; color: #474747; }
.fw-card:hover { border-color: #212121; transform: none; background: rgba(255,255,255,.02); }
.fw-card .fw-name { font-weight: 400; font-size: 15px; color: #f3f3f3; padding-right: 32px; }
.fw-card .fw-desc { color: #9c9c9c; }
.fw-card .fw-links a { color: #9c9c9c; border-bottom: 1px solid #212121; }
.fw-card .fw-links a:hover { color: #f3f3f3; border-bottom-color: #f3f3f3; }

/* 双极量尺：刻度行 + 3px 轨道 + 呼吸点游标 */
.bipolar { gap: 0; }
.bp-row { padding: 20px 0; border-bottom: 1px solid #212121; }
.bp-row:first-child { padding-top: 0; }
.bp-row:last-child { border-bottom: 0; padding-bottom: 4px; }
.bp-row .bp-ends { font-size: 13px; }
.bp-row .bp-ends b { font-weight: 400; color: #f3f3f3; }
.bp-row .bp-ends .bp-val { font-family: var(--font-num); color: #9c9c9c; font-size: 11px; letter-spacing: .08em; }
.bp-track { height: 3px; border-radius: 0; background: #1a1a1a; }
.bp-fill { border-radius: 0; background: #f3f3f3; }
.bp-thumb { width: 8px; height: 8px; border-radius: 50%; background: #ffffff; box-shadow: 0 0 0 3px #101010; animation: pulseDot 2.2s ease-in-out infinite; }

/* 红线 / 盲区 / 修正史：去彩色，发丝线清单 */
.red-item { border: 1px solid #212121; border-left: 2px solid #f3f3f3; background: transparent; border-radius: 0; color: #f3f3f3; padding: 12px 16px; }
.gap-item { border: 1px solid #212121; background: transparent; border-radius: 0; color: #9c9c9c; padding: 12px 16px; }
.corr-item { border-bottom: 1px dashed #212121; font-family: var(--font-num); font-size: 12.5px; letter-spacing: .02em; color: #9c9c9c; padding: 14px 0; }

/* 活动热力图：方格灰阶 */
.hm-cell { border-radius: 0; background: #161616; }
.hm-cell.l1 { background: rgba(243,243,243,.18); }
.hm-cell.l2 { background: rgba(243,243,243,.38); }
.hm-cell.l3 { background: rgba(243,243,243,.62); }
.hm-cell.l4 { background: #f3f3f3; }
.hm-legend { font-family: var(--font-num); letter-spacing: .06em; }

/* ===== 导入按钮 / 拖拽遮罩 ===== */
#btn-import { border-radius: 0; border-color: #212121; background: transparent; color: #9c9c9c; font: 400 11px/1 var(--font-num); letter-spacing: .14em; text-transform: uppercase; padding: 9px 16px; }
#btn-import:hover { border-color: #f3f3f3; color: #f3f3f3; }
#drop-mask { background: rgba(8,8,8,.9); backdrop-filter: none; -webkit-backdrop-filter: none; }
#drop-mask .drop-inner { border: 1px dashed #474747; border-radius: 0; background: #080808; padding: 60px 80px; }
#drop-mask b { font-weight: 400; letter-spacing: -.01em; }
#drop-mask span { font-family: var(--font-num); font-size: 11px; letter-spacing: .04em; color: #9c9c9c; }

/* ===== 弹窗 → Headline Display Block：44px weight 400 负字距大标题 ===== */
#modal { border-radius: 0; box-shadow: none; border-color: #212121; background: #0d0d0d; padding: 52px 56px 48px; }
#modal .close-x { font-family: var(--font-num); font-weight: 400; }
#modal h2 { font-weight: 400; font-size: clamp(28px, 3.2vw, 44px); line-height: 1.07; letter-spacing: -.007em; margin-bottom: 18px; }
#modal .mmeta { font-family: var(--font-num); font-size: 11px; letter-spacing: .08em; text-transform: uppercase; padding-bottom: 20px; border-bottom: 1px solid #212121; margin-bottom: 24px; }
#modal .mbody { border-top: 0; padding-top: 0; }
.mbody h2 { font-family: var(--font-num) !important; font-weight: 400 !important; font-size: 11px !important; letter-spacing: .3em !important; text-transform: uppercase; color: #9c9c9c !important; }
#modal .edit-area { border-radius: 0; background: #080808; border-color: #212121; font-family: var(--font-num); }
#modal .edit-area:focus { border-color: #f3f3f3; }

/* ===== 规划页：计划卡纵向堆叠为发丝线清单 + 编号前缀 ===== */
.plan-list { gap: 0; border: 1px solid #212121; border-bottom: 0; margin-top: 40px; counter-reset: planitem; }
.plan-card { background: transparent; border: 0; border-bottom: 1px solid #212121; border-radius: 0; padding: 38px 40px; box-shadow: none; backdrop-filter: none; counter-increment: planitem; }
.plan-card:hover { border-color: #212121; background: rgba(255,255,255,.02); }
.plan-head .ptitle { font-weight: 400; font-size: 21px; letter-spacing: -.01em; }
.plan-head .ptitle::before { content: counter(planitem, decimal-leading-zero) " / "; font-family: var(--font-num); font-size: 12px; letter-spacing: .1em; color: #474747; }
.status-badge { border-radius: 0; background: #1a1a1a; border-color: #212121; font-family: var(--font-num); font-size: 10px; letter-spacing: .14em; text-transform: uppercase; padding: 6px 13px; color: #9c9c9c; }
.status-badge.active { color: #9c9c9c; border-color: #212121; background: #1a1a1a; }
.status-badge.active::before { content: ""; display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: #98ff38; margin-right: 8px; vertical-align: 1px; animation: pulseDot 2.2s ease-in-out infinite; }
@keyframes pulseDot { 0%, 100% { opacity: 1; } 50% { opacity: .3; } }
.plan-meta, .progress-num { font-family: var(--font-num); }
.progress-track { background: #1a1a1a; border-radius: 0; height: 3px; }
.progress-fill { background: #f3f3f3; border-radius: 0; }
.task { border-bottom: 1px dashed #212121; }
.task input[type="checkbox"] { border-radius: 0; border-color: #474747; }
.task input[type="checkbox"]:hover { border-color: #f3f3f3; }
.task input[type="checkbox"]:checked { background: #f3f3f3; border-color: #f3f3f3; }
.task input[type="checkbox"]:checked::after { color: #101010; }
.plan-basis { border-top-color: #212121; }

/* ===== 图谱 / 时间线：月份行 = 发丝线分节标头，条目退化为分隔线行 ===== */
#graph-box { border-radius: 0; background: transparent; border-color: #212121; box-shadow: none; backdrop-filter: none; }
.tl { margin-top: 40px; }
.tl::before { background: #212121; }
.tl-month { margin-bottom: 48px; }
.tl-month::before { border-radius: 0; width: 7px; height: 7px; left: -25px; top: 7px; background: #f3f3f3; box-shadow: none; }
.tl-month .mname { font-family: var(--font-num); font-weight: 400; font-size: 13px; letter-spacing: .22em; text-transform: uppercase; color: #9c9c9c; margin-bottom: 18px; display: flex; align-items: center; gap: 16px; }
.tl-month .mname::after { content: ""; flex: 1; height: 1px; background: #212121; }
.tl-item { border-radius: 0; background: transparent; border: 0; border-bottom: 1px solid #212121; backdrop-filter: none; padding: 16px 4px 16px 0; margin-bottom: 0; }
.tl-item:hover { transform: none; border-color: #212121; background: rgba(255,255,255,.02); }
.tl-item .t { font-weight: 400; font-size: 15px; color: #f3f3f3; }
.tl-item .d { font-family: var(--font-num); font-size: 11px; letter-spacing: .04em; }

/* ===== 状态栏 / 通知 ===== */
#status-bar { background: #080808; backdrop-filter: none; border-top-color: #212121; font-family: var(--font-num); font-size: 11px; letter-spacing: .04em; }
#toast { border-radius: 0; border-color: #212121; box-shadow: none; font-family: var(--font-num); font-size: 12px; }

@media (max-width: 960px) {
  .hero { padding: 64px 0 0; }
  .sig { height: 26vh; min-height: 180px; margin-top: 56px; }
  .insight-grid { grid-template-columns: 1fr; }
  .insight-grid .panel { border-top: 1px solid #212121; border-left: 0; }
  .insight-grid .panel:first-child { border-top: 0; }
  #drop-mask .drop-inner { padding: 40px 28px; }
  .panel { padding: 28px; }
  .stat-row, .dash-grid { margin-top: 48px; }
  .stat { border-left: 0; border-top: 1px solid #212121; }
  .stat:nth-child(-n+2) { border-top: 0; }
  .stat:nth-child(even) { border-left: 1px solid #212121; }
  .rail { border-left: 0; border-top: 1px solid #212121; }
  #modal { padding: 36px 28px; }
}

/* ---- 签名视觉：Dot-Map World Graphic，横跨 hero 底部的点阵星球横幅 ---- */
.sig { display: block; grid-column: 1 / -1; order: 9; width: 100vw; height: 36vh; min-height: 260px; margin: 80px 0 0 calc(50% - 50vw); border-top: 1px solid #212121; background: #080808; }
